const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/listparse";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "math.test.mjs"), [
  "import { describe, test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "writeFileSync(new URL('./executed.txt', import.meta.url), 'yes')",
  "describe('math', () => {",
  "  test('adds', () => {})",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "list"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
if (!/math > adds/.test(out)) {
  console.error("ERROR: vitest list did not print math > adds (exit " + r.status + ")");
  process.exit(2);
}
const executed = fs.existsSync(path.join(dir, "executed.txt"));
if (!executed) {
  console.log("PASS: vitest list collected math > adds without running the test file");
  process.exit(0);
}
console.error("FAIL: vitest list ran the test file's top-level code to collect tests");
process.exit(1);

